class Solution {public:vector<int> minimumTime(int n,vector<vector<int>>& edges,vector<int>& disappear){
 vector<vector<pair<int,int>>> g(n);for(auto &e:edges){g[e[0]].push_back({e[1],e[2]});g[e[1]].push_back({e[0],e[2]});}
 vector<int> d(n,INT_MAX);priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pq;
 if(disappear[0]>0){d[0]=0;pq.push({0,0});}
 while(!pq.empty()){auto cur=pq.top();pq.pop();int t=cur.first,u=cur.second;if(t!=d[u])continue;
 for(auto e:g[u]){int v=e.first,nt=t+e.second;if(nt<d[v]&&nt<disappear[v]){d[v]=nt;pq.push({nt,v});}}}
 for(int &x:d)if(x==INT_MAX)x=-1;return d;
}};
